(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const out = {};
  for (let i = 0; i < 16; i++) {
    await sleep(400);
    if (document.querySelector('.pc-msg')) break;
  }
  out.hint = document.querySelector('.pc-msg')?.textContent || null;
  out.editorOpened = !!document.querySelector('.pc-textarea');
  out.fileCount = document.querySelectorAll('.pc-item-name').length;
  out.tabs = [...document.querySelectorAll('.pc-tab')].map((b) => b.textContent.trim());
  return JSON.stringify(out);
})()
